    def convert_to_integer(string):
        return int(string)

    def sum_integers(integer1, integer2):
        return integer1 + integer2

    def array_to_number(array):
        sign = 1
        if array[0] < 0:
            sign = -1
            array = array[1:]
        number = 0
        for digit in array:
            number = number * 10 + digit
        return sign * number

    def number_to_array(number):
        if number == 0:
            return [0]
        sign = 1 if number >= 0 else -1
        number = abs(number)
        array = []
        while number > 0:
            array.append(number % 10)
            number //= 10
        if sign == -1:
            array.append('-')
        return array[::-1]

    num1 = array_to_number(array1)
    num2 = array_to_number(array2)
    result = sum_integers(num1, num2)
    return number_to_array(result)
```

