def sum_arrays(array1, array2):
    def concatenate_and_convert(array):
        return int(''.join(map(str, array)))

    def convert_and_sum(array1, array2):
        return sum_integers(concatenate_and_convert(array1), concatenate_and_convert(array2))

    return [int(digit) for digit in str(convert_and_sum(array1, array2))]
