def sum_arrays(array1, array2):
    def array_to_int(array):
        return int(''.join(map(str, array)))

    def int_to_array(number):
        return [int(digit) for digit in str(number)]

    int1 = array_to_int(array1)
    int2 = array_to_int(array2)
    sum_int = sum_integers(int1, int2)
    return int_to_array(sum_int)
