def calculate_differences(freq_s: dict, freq_t: dict) -> int:
    differences = 0
    for char, count in freq_s.items():
        if char in freq_t:
            differences += abs(count - freq_t[char])
        else:
            differences += count
    for char, count in freq_t.items():
        if char not in freq_s:
            differences += count
    return differences // 2
