from collections import Counter

def calculate_differences(freq_s: dict, freq_t: dict) -> int:
    return sum((freq_s - freq_t).values())

def create_anagram(s: str, t: str) -> int:
    freq_s = Counter(s)
    freq_t = Counter(t)
    return calculate_differences(freq_s, freq_t)
